'use strict';
/** 浏览器剪贴板适配：富文本与PNG可写入；任意文件交给下载或系统分享。 */
(function exposeClipboard(){
  /** @brief 提取记录正文中的本地文件引用。 @param {object} note 记录。 @return {string[]} 去重引用。 */
  function references(note){const output=[];for(const match of note.text.matchAll(/\]\((sidenotes-file:[^\s)]+|file:\/\/[^)]+|[a-zA-Z]:[\\/][^)]+)\)/g)){const ref=window.NoteContent.filePath(match[1]);if(ref&&!output.includes(ref))output.push(ref);}for(const line of note.text.split(/\r?\n/)){const ref=window.NoteContent.filePath(line.trim());if(ref&&!output.includes(ref))output.push(ref);}return output;}
  /** @brief 准备安全富文本，Emoji是记录标题的一部分。 @param {object} note 记录。 @return {object} 纯文本和HTML。 */
  function formats(note){const wrapper=document.createElement('div'),heading=document.createElement('p'),firstLine=note.text.split(/\r?\n/).find(function nonempty(line){return line.trim();})||'',structured=/^\s*(?:[-*+]\s|\d+[.)]\s|>|`{3,}|~{3,}|!\[)/.test(firstLine);heading.textContent=(note.emoji||'📝')+' '+(structured?'记录':firstLine.replace(/^#{1,6}\s+/,'')||'图片记录');wrapper.append(heading);const body=document.createElement('div');const first=note.text.indexOf('\n');window.NoteContent.renderMarkdown(structured?note.text:first>=0?note.text.slice(first+1):'',body);body.querySelectorAll('button[data-action="open-file-reference"]').forEach(function fileName(node){const label=document.createElement('span');label.textContent=node.textContent;node.replaceWith(label);});body.querySelectorAll('button').forEach(function unwrap(node){node.replaceWith(...node.childNodes);});wrapper.append(body);note.images.forEach(function image(attachment){const img=document.createElement('img');img.src=attachment.data;img.alt=attachment.name;img.style.maxWidth='100%';wrapper.append(img);});return {text:(note.emoji||'📝')+' '+note.text,html:wrapper.innerHTML,body:wrapper};}
  /** @brief 加载可安全绘制到剪贴板图片中的记录图片。 @param {string} source 图片源。 @return {Promise<HTMLImageElement>} 图片。 */
  function loadImage(source){return new Promise(function imagePromise(resolve,reject){const image=new Image();image.crossOrigin='anonymous';image.onload=function loaded(){resolve(image);};image.onerror=function failed(){reject(new Error('图片无法读取'));};image.src=source;});}
  /** @brief 生成包含Emoji正文和全部可读图片的PNG，供只接收图片的应用粘贴。 @param {object} note 记录。 @return {Promise<Blob>} PNG数据。 */
  async function raster(note){
    const sources=note.images.map(function source(image){return image.data;});for(const match of note.text.matchAll(/!\[[^\]]*\]\(([^\s)]+)\)/g))if(!sources.includes(match[1]))sources.push(match[1]);
    const loaded=await Promise.allSettled(sources.map(loadImage)),images=loaded.filter(function okay(result){return result.status==='fulfilled';}).map(function value(result){return result.value;});if(!images.length)throw new Error('没有可复制的图片');
    const canvas=document.createElement('canvas'),context=canvas.getContext('2d');if(!context)throw new Error('图片剪贴板不可用');canvas.width=800;context.font='24px "Segoe UI","Microsoft YaHei",sans-serif';const text=(note.emoji||'📝')+' '+note.text.replace(/!\[[^\]]*\]\([^)]+\)/g,'').trim(),lines=[];
    for(const paragraph of text.split(/\r?\n/)){let line='';for(const character of paragraph){if(context.measureText(line+character).width>720){lines.push(line);line='';}line+=character;}lines.push(line);}const heights=images.map(function height(image){return Math.round(Math.min(736/image.naturalWidth,1)*image.naturalHeight);});const height=64+lines.length*35+heights.reduce(function total(sum,value){return sum+value+18;},0);if(height>14000)throw new Error('记录过长，请分别复制图片');canvas.height=Math.max(100,height);context.fillStyle='#ffffff';context.fillRect(0,0,canvas.width,canvas.height);context.fillStyle='#26312a';context.font='24px "Segoe UI","Microsoft YaHei",sans-serif';let y=43;for(const line of lines){context.fillText(line,32,y);y+=35;}for(let index=0;index<images.length;index++){const image=images[index],width=Math.min(736,image.naturalWidth);context.drawImage(image,32,y,width,heights[index]);y+=heights[index]+18;}
    return new Promise(function blobPromise(resolve,reject){canvas.toBlob(function made(blob){if(blob)resolve(blob);else reject(new Error('图片生成失败'));},'image/png');});
  }
  /** @brief 复制多种表示；失败时保留完整文字降级。 @param {object} note 记录。 @return {Promise<object>} 复制结果和附件交接信息。 */
  async function copy(note){
    const data=formats(note),refs=references(note),hasImages=note.images.length>0||/!\[[^\]]*\]\(/.test(note.text);let kind='text',imageError='';
    if(navigator.clipboard&&navigator.clipboard.write&&window.ClipboardItem){const formats={'text/plain':new Blob([data.text],{type:'text/plain'}),'text/html':new Blob([data.html],{type:'text/html'})};if(hasImages&&(!ClipboardItem.supports||ClipboardItem.supports('image/png'))){formats['image/png']=raster(note).catch(function noImage(error){imageError=error.message;throw error;});kind='image';}else kind='rich';try{await navigator.clipboard.write([new ClipboardItem(formats)]);}catch(error){if(kind==='image'){delete formats['image/png'];kind='rich';try{await navigator.clipboard.write([new ClipboardItem(formats)]);}catch(fallback){if(!navigator.clipboard.writeText)throw fallback;await navigator.clipboard.writeText(data.text);kind='text';}}else{if(!navigator.clipboard.writeText)throw error;await navigator.clipboard.writeText(data.text);kind='text';}}}
    else if(navigator.clipboard&&navigator.clipboard.writeText)await navigator.clipboard.writeText(data.text);else throw new Error('当前环境不允许访问剪贴板');
    if(hasImages&&kind!=='image'&&!imageError)imageError='此环境未写入图片剪贴板；可保存图片，或粘贴到支持富文本的应用。';
    return {kind:kind,refs:refs,text:data.text,imageError:imageError};
  }
  /** @brief 读取本次会话已绑定的真实文件。 @param {string} ref 文件引用。 @return {Promise<File|null>} 可用文件。 */
  async function file(ref){if(await window.NoteContent.checkFile(ref)!=='valid')return null;const entry=window.NoteContent.files.get(window.NoteContent.fileKey(ref));return entry?(entry.handle?await entry.handle.getFile():entry.file):null;}
  /** @brief 保存所选真实文件副本。 @param {File} file 文件。 */
  function download(file){const url=URL.createObjectURL(file),link=document.createElement('a');link.href=url;link.download=file.name||'附件';document.body.append(link);link.click();link.remove();window.setTimeout(function release(){URL.revokeObjectURL(url);},60000);}
  window.NoteClipboard=Object.freeze({copy:copy,formats:formats,references:references,file:file,download:download,raster:raster});
})();
